// Mô phỏng quá trình Encapsulation / Decapsulation qua các tầng OSI trong TypeScript
interface PacketHeader {
  l7Payload: string;          // L7 Application: HTTP GET /api/v1/users
  l6Encoding?: string;        // L6 Presentation: UTF-8, gzip, TLS
  l4Transport: {              // L4 Transport: Segment (TCP/UDP)
    srcPort: number;
    dstPort: number;
    protocol: 'TCP' | 'UDP';
  };
  l3Network: {                // L3 Network: Packet (IP routing)
    srcIp: string;
    dstIp: string;
    ttl: number;
  };
  l2DataLink: {               // L2 Data Link: Frame (MAC address)
    srcMac: string;
    dstMac: string;
  };
}

class NetworkStackSimulator {
  // Quá trình gửi: Encapsulation từ L7 xuống L2
  static encapsulate(httpData: string, srcIp: string, dstIp: string): PacketHeader {
    return {
      l7Payload: httpData,
      l6Encoding: "application/json; charset=utf-8",
      l4Transport: { srcPort: 54321, dstPort: 443, protocol: "TCP" },
      l3Network: { srcIp, dstIp, ttl: 64 },
      l2DataLink: { srcMac: "00:1A:2B:3C:4D:5E", dstMac: "00:50:56:C0:00:08" }
    };
  }

  // Quá trình nhận: Decapsulation từ L2 lên L7
  static decapsulate(frame: PacketHeader): string {
    console.log(`[L2 Frame] MAC ${frame.l2DataLink.srcMac} -> ${frame.l2DataLink.dstMac}`);
    console.log(`[L3 Packet] IP ${frame.l3Network.srcIp} -> ${frame.l3Network.dstIp}, TTL=${frame.l3Network.ttl}`);
    console.log(`[L4 Segment] Port ${frame.l4Transport.srcPort} -> ${frame.l4Transport.dstPort} (${frame.l4Transport.protocol})`);
    return frame.l7Payload;
  }
}

