// So sánh TCP Client (đảm bảo tin cậy) vs UDP Client (tối ưu độ trễ) trong Node.js
import net from 'node:net';
import dgram from 'node:dgram';

// 1. TCP Client: Bắt tay 3 bước, đảm bảo byte stream toàn vẹn
export function sendReliableTcpPayload(data: string, host: string, port: number): Promise<string> {
  return new Promise((resolve, reject) => {
    const client = net.createConnection({ host, port }, () => {
      client.write(data);
    });
    client.setTimeout(3000);
    client.on('data', (response) => {
      resolve(response.toString());
      client.end();
    });
    client.on('error', reject);
    client.on('timeout', () => { client.destroy(); reject(new Error('TCP timeout')); });
  });
}

// 2. UDP Client: Fire and forget, không connection handshake, zero HoL blocking
export function sendFastUdpTelemetry(metric: Buffer, host: string, port: number): void {
  const socket = dgram.createSocket('udp4');
  socket.send(metric, 0, metric.length, port, host, (err) => {
    if (err) console.error('UDP send error:', err);
    socket.close();
  });
}

// Thuật toán kiểm tra 2 IP có cùng Subnet không bằng Bitwise AND trong TypeScript
export function isSameSubnet(ip1: string, ip2: string, cidrMaskBits: number): boolean {
  const ipToLong = (ip: string): number => {
    return ip.split('.').reduce((acc, octet) => ((acc << 8) + parseInt(octet, 10)) >>> 0, 0);
  };

  const num1 = ipToLong(ip1);
  const num2 = ipToLong(ip2);
  // Tạo mask: ví dụ /24 -> 24 bit 1, 8 bit 0
  const mask = cidrMaskBits === 0 ? 0 : (~0 << (32 - cidrMaskBits)) >>> 0;

  const network1 = (num1 & mask) >>> 0;
  const network2 = (num2 & mask) >>> 0;

  return network1 === network2;
}

// Test: 192.168.1.15 và 192.168.1.200 với /24 -> True (Cùng LAN, không cần Gateway)
console.log(isSameSubnet('192.168.1.15', '192.168.1.200', 24)); // true
// Test: 192.168.1.15 và 192.168.2.10 với /24 -> False (Khác subnet, PHẢI gửi qua Default Gateway)
console.log(isSameSubnet('192.168.1.15', '192.168.2.10', 24)); // false

// Đo thời gian phân giải DNS (DNS lookup latency) chi tiết bằng Node.js
import dns from 'node:dns/promises';
import { performance } from 'node:perf_hooks';

async function benchmarkDnsResolution(domain: string) {
  console.log(`Benchmarking DNS lookup for: ${domain}`);

  // 1. Phân giải bằng system resolver mặc định (có thể ăn OS cache)
  const startCached = performance.now();
  const cachedLookup = await dns.lookup(domain);
  const timeCached = (performance.now() - startCached).toFixed(2);
  console.log(`System Resolver (Cached): ${cachedLookup.address} (${timeCached} ms)`);

  // 2. Phân giải trực tiếp qua Resolver chuyên dụng không dùng cache hệ điều hành
  const resolver = new dns.Resolver();
  resolver.setServers(['1.1.1.1', '8.8.8.8']); // Cloudflare & Google Public DNS

  const startDirect = performance.now();
  const directRecords = await resolver.resolve4(domain, { ttl: true });
  const timeDirect = (performance.now() - startDirect).toFixed(2);
  console.log(`Authoritative Query via 1.1.1.1:`, directRecords);
  console.log(`Lookup Latency: ${timeDirect} ms`);
}

benchmarkDnsResolution('google.com');

// Script kiểm tra nhanh trạng thái cổng dịch vụ (Port Scanner / Health Check) bằng TypeScript
import net from 'node:net';

interface PortCheckResult {
  port: number;
  service: string;
  isOpen: boolean;
  latencyMs: number;
}

const standardPorts: Record<number, string> = {
  22: 'SSH',
  53: 'DNS',
  80: 'HTTP',
  443: 'HTTPS',
  3306: 'MySQL',
  5432: 'PostgreSQL',
  6379: 'Redis',
};

export async function checkPort(host: string, port: number, timeout = 1000): Promise<PortCheckResult> {
  const start = Date.now();
  return new Promise((resolve) => {
    const socket = new net.Socket();
    socket.setTimeout(timeout);

    socket.connect(port, host, () => {
      const latencyMs = Date.now() - start;
      socket.destroy();
      resolve({ port, service: standardPorts[port] || 'Unknown', isOpen: true, latencyMs });
    });

    socket.on('error', () => {
      resolve({ port, service: standardPorts[port] || 'Unknown', isOpen: false, latencyMs: Date.now() - start });
    });

    socket.on('timeout', () => {
      socket.destroy();
      resolve({ port, service: standardPorts[port] || 'Unknown', isOpen: false, latencyMs: Date.now() - start });
    });
  });
}

// Minh họa: Worker Threads chia sẻ SharedArrayBuffer vs cô lập bộ nhớ trong Node.js
import { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';

if (isMainThread) {
  // Tạo vùng nhớ chia sẻ (Shared Memory) giữa các luồng
  const sharedBuffer = new SharedArrayBuffer(4); // 4 bytes Int32
  const sharedInt32 = new Int32Array(sharedBuffer);
  sharedInt32[0] = 100;

  console.log('[Main Thread] Khởi tạo shared value:', sharedInt32[0]);

  const worker = new Worker(__filename, { workerData: { sharedBuffer } });
  worker.on('message', (msg) => {
    console.log('[Main Thread] Nhận thông báo từ worker:', msg);
    console.log('[Main Thread] Giá trị sau khi worker sửa trực tiếp:', sharedInt32[0]);
  });
} else {
  // Luồng con: truy cập trực tiếp cùng địa chỉ RAM với luồng chính
  const { sharedBuffer } = workerData;
  const sharedInt32 = new Int32Array(sharedBuffer);

  // Thao tác atomic để tránh data race giữa các CPU cores
  Atomics.add(sharedInt32, 0, 50); // 100 + 50 = 150
  parentPort?.postMessage('Đã cập nhật SharedArrayBuffer thành công');
}

