// Chiến lược xử lý song song đúng đắn cho CPU-bound vs I/O-bound trong Node.js
import os from 'node:os';
import { Worker } from 'node:worker_threads';

// 1. Tác vụ I/O-bound: Sử dụng Non-blocking Async I/O thuần túy (Không cần Worker Thread)
export async function handleIoBoundTask(urls: string[]): Promise<string[]> {
  // Hàng ngàn I/O requests chạy đồng thời trên single-thread event loop cực kỳ nhẹ
  return Promise.all(urls.map(async (url) => {
    const res = await fetch(url);
    return res.text();
  }));
}

// 2. Tác vụ CPU-bound (Ví dụ mã hóa hash nặng): Đẩy sang Worker Pool để không block Event Loop
export function handleCpuBoundComputation(data: number[]): Promise<number> {
  return new Promise((resolve, reject) => {
    // Worker chạy trên OS Thread riêng biệt trên core CPU khác
    const workerScript = `
      const { parentPort, workerData } = require('node:worker_threads');
      // Mô phỏng tính toán nặng tiêu tốn chu kỳ CPU
      let sum = 0;
      for (const n of workerData) {
        sum += Math.sqrt(n) * Math.sin(n);
      }
      parentPort.postMessage(sum);
    `;
    const worker = new Worker(workerScript, { eval: true, workerData: data });
    worker.on('message', resolve);
    worker.on('error', reject);
  });
}

