// Bash script kiểm tra và phát hiện Zombie Processes và D-state Processes trên Linux
/*
#!/usr/bin/env bash

echo "=== Kiếm tra trạng thái Processes trên hệ thống ==="

# 1. Liệt kê các tiến trình Zombie (STAT có chữ Z)
