ps -eo pid,ppid,stat,cmd | awk '$3 ~ /^Z/ { print "Zombie PID: " $1 " | PPID: " $2 " | Cmd: " $4 }'

# 2. Liệt kê các tiến trình kẹt I/O không thể ngắt (STAT có chữ D)
echo "--- Danh sách Uninterruptible Sleep (D-state) ---"
ps -eo pid,ppid,stat,cmd | awk '$3 ~ /^D/ { print "D-state PID: " $1 " | PPID: " $2 " | Cmd: " $4 }'
*/

import { execSync } from 'node:child_process';

export function getSystemProcessStats(): { total: number; zombies: number } {
  try {
    const output = execSync('ps -eo stat', { encoding: 'utf8' });
    const stats = output.split('\n');
    let zombies = 0;
    for (const s of stats) {
      if (s.trim().startsWith('Z')) zombies++;
    }
    return { total: stats.length, zombies };
  } catch {
    return { total: 0, zombies: 0 };
  }
}

// Giả lập trạng thái TCP 3-Way Handshake bằng TypeScript State Machine
type TcpState = 'CLOSED' | 'SYN_SENT' | 'SYN_RECEIVED' | 'ESTABLISHED';

class TcpHandshakeSimulator {
  private state: TcpState = 'CLOSED';
  private clientIsn = 0;
  private serverIsn = 0;

  // Bước 1: Client gửi SYN
  clientSendSyn(): { flag: 'SYN'; seq: number } {
    this.clientIsn = Math.floor(Math.random() * 100000);
    this.state = 'SYN_SENT';
    console.log(`[Step 1] Client -> Server: SYN (seq=${this.clientIsn})`);
    return { flag: 'SYN', seq: this.clientIsn };
  }

  // Bước 2: Server nhận SYN, cấp phát ISN và trả lời SYN-ACK
  serverReceiveSyn(clientSeq: number): { flag: 'SYN-ACK'; seq: number; ack: number } {
    this.serverIsn = Math.floor(Math.random() * 200000);
    this.state = 'SYN_RECEIVED';
    const ackNumber = clientSeq + 1;
    console.log(`[Step 2] Server -> Client: SYN-ACK (seq=${this.serverIsn}, ack=${ackNumber})`);
    return { flag: 'SYN-ACK', seq: this.serverIsn, ack: ackNumber };
  }

  // Bước 3: Client nhận SYN-ACK, gửi ACK hoàn tất kết nối
  clientCompleteHandshake(serverSeq: number): { flag: 'ACK'; ack: number } {
    const ackNumber = serverSeq + 1;
    this.state = 'ESTABLISHED';
    console.log(`[Step 3] Client -> Server: ACK (ack=${ackNumber}) -> Trạng thái: ESTABLISHED`);
    return { flag: 'ACK', ack: ackNumber };
  }
}

const sim = new TcpHandshakeSimulator();
const syn = sim.clientSendSyn();
const synAck = sim.serverReceiveSyn(syn.seq);
sim.clientCompleteHandshake(synAck.seq);

// Minh họa: Tái sử dụng socket bằng HTTP Keep-Alive Agent để TRÁNH tình trạng TIME_WAIT bùng nổ
import http from 'node:http';

// 1. SAI LẦM: Tạo Agent mới hoặc disable keep-alive -> Mỗi request sinh 1 TCP connection -> 4-way close -> TIME_WAIT
export function badRequestWithoutPool(url: string) {
  return new Promise((resolve) => {
    http.get(url, { agent: false }, (res) => { // agent: false buộc đóng socket sau mỗi request
      res.on('data', () => {});
      res.on('end', resolve);
    });
  });
}

// 2. CHUẨN MỰC SENIOR: Sử dụng Connection Pooling (Keep-Alive) -> Tái sử dụng socket, không bao giờ vào TIME_WAIT
const keepAliveAgent = new http.Agent({
  keepAlive: true,
  maxSockets: 100,       // Tối đa 100 concurrent sockets cho mỗi origin
  maxFreeSockets: 10,    // Duy trì 10 idle sockets sẵn sàng nhận việc
  timeout: 60000,
});

export function goodRequestWithPool(url: string) {
  return new Promise((resolve) => {
    http.get(url, { agent: keepAliveAgent }, (res) => {
      res.on('data', () => {});
      res.on('end', resolve);
    });
  });
}

// Mô phỏng thuật toán TCP Slow Start và Congestion Avoidance bằng TypeScript
class TcpCongestionControlSimulator {
  private cwnd = 1;        // Khởi tạo Congestion Window = 1 MSS
  private ssthresh = 16;   // Ngưỡng Slow Start Threshold = 16 MSS
  private rttRound = 0;

  simulateTransmission(totalRtt: number) {
    console.log(`Bắt đầu mô phỏng: Initial cwnd=${this.cwnd}, ssthresh=${this.ssthresh}`);

    for (let rtt = 1; rtt <= totalRtt; rtt++) {
      this.rttRound = rtt;

      if (rtt === 8) {
        // Giả lập sự kiện mất gói tin (Packet Loss phát hiện qua 3 Dup ACKs)
        console.log(`---> [RTT ${rtt}] PHÁT HIỆN MẤT GÓI TIN! Kích hoạt Fast Retransmit & Recovery`);
        this.ssthresh = Math.max(2, Math.floor(this.cwnd / 2));
        this.cwnd = this.ssthresh; // Chuyển sang Congestion Avoidance
      } else if (this.cwnd < this.ssthresh) {
        // Giai đoạn Slow Start: Tăng theo cấp số nhân (x2 mỗi RTT)
        this.cwnd *= 2;
        console.log(`[RTT ${rtt}] Slow Start: cwnd = ${this.cwnd} MSS`);
      } else {
        // Giai đoạn Congestion Avoidance: Tăng tuyến tính (+1 mỗi RTT)
        this.cwnd += 1;
        console.log(`[RTT ${rtt}] Congestion Avoidance: cwnd = ${this.cwnd} MSS`);
      }
    }
  }
}

const tcpSim = new TcpCongestionControlSimulator();
tcpSim.simulateTransmission(12);

