// Mô phỏng luồng Socket Programming chuẩn POSIX trong TypeScript / Node.js
import net from 'node:net';

// 1. Phía Server: Tương ứng socket() -> bind() -> listen() -> accept()
export function startTcpServer(port: number, host: string) {
  // socket() + bind() + listen() được đóng gói trong net.createServer().listen()
  const server = net.createServer((connectedSocket) => {
    // accept() đã thành công, trả về 'connectedSocket' riêng biệt cho client này
    console.log(`[Server] Accept connection mới từ: ${connectedSocket.remoteAddress}:${connectedSocket.remotePort}`);

    connectedSocket.on('data', (buffer) => {
      // read() syscall từ socket file descriptor
      console.log(`[Server] Đọc dữ liệu: ${buffer.toString().trim()}`);
      // write() syscall xuống socket file descriptor
      connectedSocket.write('Echo: ' + buffer.toString());
    });

    connectedSocket.on('end', () => {
      // close() syscall
      console.log('[Server] Client đã đóng kết nối');
    });
  });

  server.listen(port, host, 511, () => {
    // 511 là kích thước tham số backlog truyền vào syscall listen()
    console.log(`[Server] Đang listen trên ${host}:${port} với backlog=511`);
  });
}

// 2. Phía Client: Tương ứng socket() -> connect()
export function startTcpClient(port: number, host: string) {
  const client = net.createConnection({ port, host }, () => {
    // connect() syscall thành công (3-way handshake hoàn tất)
    console.log('[Client] Đã kết nối thành công đến server!');
    client.write('Xin chào từ Socket Client!\n');
  });

  client.on('data', (data) => {
    console.log('[Client] Nhận phản hồi:', data.toString().trim());
    client.end();
  });
}

// Giả lập bảng dịch địa chỉ NAT (NAT Translation Table) trong TypeScript
interface NatTableEntry {
  internalIp: string;
  internalPort: number;
  externalPort: number;
  destinationIp: string;
  destinationPort: number;
  createdAt: number;
}

class NatRouterSimulator {
  private publicIp = '203.0.113.5';
  private natTable = new Map<number, NatTableEntry>();
  private nextEphemeralPort = 40000;

  // Chiều ra: Chuyển dịch IP/Port nội bộ thành Public IP/Port
  outboundTranslate(internalIp: string, internalPort: number, dstIp: string, dstPort: number) {
    const externalPort = this.nextEphemeralPort++;
    const entry: NatTableEntry = {
      internalIp,
      internalPort,
      externalPort,
      destinationIp: dstIp,
      destinationPort: dstPort,
      createdAt: Date.now(),
    };
