// Minh họa: Tác động của CPU Cache & Paging locality (Row-major vs Column-major traversal)
import { performance } from 'node:perf_hooks';

const ROWS = 4096;
const COLS = 4096;
// Mảng 2D kích thước 16 triệu phần tử (chiếm ~64MB bộ nhớ)
const matrix = new Int32Array(ROWS * COLS);

// 1. Duyệt tuần tự theo hàng (Sequential Locality) -> Tận dụng tối đa TLB Hit và L1 Cache
function traverseRowMajor() {
  const start = performance.now();
  let sum = 0;
  for (let i = 0; i < ROWS; i++) {
    for (let j = 0; j < COLS; j++) {
      sum += matrix[i * COLS + j];
    }
  }
  return { duration: performance.now() - start, sum };
}

// 2. Duyệt nhảy cóc theo cột (Strided Traversal) -> Gây liên tục TLB Misses & Cache Misses
function traverseColumnMajor() {
  const start = performance.now();
  let sum = 0;
  for (let j = 0; j < COLS; j++) {
    for (let i = 0; i < ROWS; i++) {
      sum += matrix[i * COLS + j];
    }
  }
  return { duration: performance.now() - start, sum };
}

const rowResult = traverseRowMajor();
const colResult = traverseColumnMajor();
console.log(`Row-major (Sequential / High TLB Hit): ${rowResult.duration.toFixed(2)} ms`);
console.log(`Col-major (Stride 4096 / High TLB Miss): ${colResult.duration.toFixed(2)} ms`);
