// Triển khai Counting Semaphore trong TypeScript để kiểm soát tài nguyên đồng thời giới hạn
class AsyncCountingSemaphore {
  private permits: number;
  private waitingQueue: Array<() => void> = [];

  constructor(permits: number) {
    this.permits = permits;
  }

  // Xin cấp phép (Acquire): Nếu hết permit, trả về Promise treo và đẩy vào hàng đợi
  async acquire(): Promise<void> {
    if (this.permits > 0) {
      this.permits--;
      return Promise.resolve();
    }
    return new Promise<void>((resolve) => {
      this.waitingQueue.push(resolve);
    });
  }

  // Trả giấy phép (Release): Đánh thức task tiếp theo trong hàng đợi
  release(): void {
    if (this.waitingQueue.length > 0) {
      const nextTask = this.waitingQueue.shift()!;
      nextTask(); // Báo hiệu cho task đang chờ tiếp tục thực thi
    } else {
      this.permits++;
    }
  }
}

