  remainingTime: number;
}

function simulateRoundRobin(tasks: Task[], timeQuantum: number) {
  const queue: Task[] = tasks.map(t => ({ ...t }));
  let currentTime = 0;
  console.log(`Bắt đầu lập lịch Round Robin (Time Quantum = ${timeQuantum}ms):`);

  while (queue.length > 0) {
    const currentTask = queue.shift()!;
    const executionTime = Math.min(currentTask.remainingTime, timeQuantum);

    currentTask.remainingTime -= executionTime;
    currentTime += executionTime;
    console.log(`[T=${currentTime}ms] Task ${currentTask.id} thực thi ${executionTime}ms (Còn lại: ${currentTask.remainingTime}ms)`);

