import fs from 'node:fs';

// Mô phỏng cách CSDL nhúng (LMDB/RocksDB) đọc ghi bản ghi nhị phân cố định qua mapped memory
interface DatabaseRecord {
  id: number;
  score: number;
}

export class MmapSimulator {
  private buffer: Buffer;

  constructor(filePath: string, sizeBytes: number) {
    // Khởi tạo file với kích thước cố định nếu chưa có
    if (!fs.existsSync(filePath)) {
      const fd = fs.openSync(filePath, 'w+');
      fs.ftruncateSync(fd, sizeBytes);
      fs.closeSync(fd);
    }
    // Đọc file thành Buffer (trong C/C++ là gọi mmap(NULL, size, PROT_READ|PROT_WRITE, MAP_SHARED, fd, 0))
    this.buffer = fs.readFileSync(filePath);
  }

  // Đọc trực tiếp tại offset O(1) không qua syscall read()
  getRecord(index: number): DatabaseRecord {
    const offset = index * 8; // Mỗi record 8 bytes (4B id + 4B score)
    const id = this.buffer.readInt32LE(offset);
    const score = this.buffer.readFloatLE(offset + 4);
    return { id, score };
  }

  // Ghi trực tiếp vào memory O(1)
  writeRecord(index: number, id: number, score: number) {
    const offset = index * 8;
    this.buffer.writeInt32LE(id, offset);
    this.buffer.writeFloatLE(score, offset + 4);
  }
}

