import { execSync } from 'node:child_process';

// Đọc log xuất ra từ eBPF ring buffer / trace pipe trong user space
export function streamEbpfTraces() {
  console.log('Theo dõi các sự kiện Kernel thời gian thực qua eBPF:');
  try {
    // Đọc kernel trace pipe nơi eBPF bpf_printk đẩy dữ liệu ra
    const output = execSync('sudo head -n 5 /sys/kernel/debug/tracing/trace_pipe', { encoding: 'utf8' });
    console.log(output);
  } catch (err) {
    console.log('eBPF trace_pipe yêu cầu quyền root / CAP_BPF trên Linux.');
  }
}
